{"path":"services.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>Offerings — {{BUSINESS_NAME}}</title>
  <style>
    :root{
      --bg:#f5efe9; --card:#fff; --accent:#8a5a44; --accent-2:#c08a5b; --muted:#6b625b; --glass: rgba(255,255,255,0.7);
      --radius:14px; --maxw:1100px;
      font-family: Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;
    }
    html,body{height:100%;}
    body{margin:0;background:linear-gradient(180deg,var(--bg),#efe7de) fixed; color:#2f2b27; -webkit-font-smoothing:antialiased;}
    header{background:linear-gradient(180deg,rgba(138,90,68,0.06),transparent);backdrop-filter: blur(6px);position:sticky;top:0;z-index:30;border-bottom:1px solid rgba(47,43,39,0.04)}
    .nav{max-width:var(--maxw);margin:0 auto;display:flex;align-items:center;gap:18px;padding:18px}
    .brand{font-weight:700;color:var(--accent);letter-spacing:0.4px}
    nav a{color:var(--muted);text-decoration:none;padding:10px;border-radius:8px}
    nav a:hover{background:var(--glass)}
    main{max-width:var(--maxw);margin:36px auto;padding:24px}
    .hero{display:grid;grid-template-columns:1fr 360px;gap:28px;align-items:center}
    .hero-card{background:linear-gradient(180deg,#fff, #fff);border-radius:var(--radius);padding:28px;box-shadow:0 8px 30px rgba(45,38,33,0.06)}
    .kicker{display:inline-block;background:linear-gradient(90deg,rgba(192,138,91,0.12),rgba(138,90,68,0.06));padding:6px 10px;border-radius:999px;color:var(--accent-2);font-weight:600;margin-bottom:12px}
    h1{margin:0 0 12px 0;font-size:28px}
    p.lead{margin:0;color:var(--muted);line-height:1.45}
    .cta-row{margin-top:18px;display:flex;gap:10px}
    .btn{display:inline-flex;align-items:center;gap:10px;padding:10px 14px;border-radius:10px;border:0;cursor:pointer;font-weight:600}
    .btn-primary{background:var(--accent);color:#fff}
    .btn-alt{background:transparent;color:var(--accent);border:1px solid rgba(138,90,68,0.12)}
    .card-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:18px;margin-top:22px}
    .service{background:var(--card);padding:16px;border-radius:12px;box-shadow:0 6px 18px rgba(45,38,33,0.04)}
    .service h3{margin:0 0 6px 0;font-size:16px;color:var(--accent)}
    .price{color:var(--accent-2);font-weight:700}
    .meta{color:var(--muted);font-size:13px}
    .process{margin-top:28px;display:flex;gap:12px;flex-wrap:wrap}
    .step{background:linear-gradient(180deg,#fff,#fbf7f3);padding:14px;border-radius:12px;flex:1;min-width:180px}
    .faq{margin-top:26px}
    .faq details{background:#fff;padding:12px;border-radius:10px;margin-bottom:10px}
    .social{display:flex;gap:12px;align-items:center;margin-top:16px}
    .badge{background:rgba(200,138,91,0.08);padding:8px 12px;border-radius:999px;color:var(--accent-2);font-weight:700}
    .reveal{opacity:0;transform:translateY(18px);transition:opacity 420ms ease,transform 420ms cubic-bezier(.2,.9,.2,1)}
    .reveal.show{opacity:1;transform:none}
    footer{max-width:var(--maxw);margin:40px auto;padding:20px;color:var(--muted);font-size:14px}
    /* Modal */
    .modal-backdrop{position:fixed;inset:0;background:rgba(15,12,10,0.5);display:none;align-items:center;justify-content:center;padding:20px;z-index:60}
    .modal{background:linear-gradient(180deg,#fff,#fbf7f3);border-radius:14px;max-width:720px;width:100%;padding:20px;box-shadow:0 20px 60px rgba(25,20,18,0.35)}
    .modal .tabs{display:flex;gap:8px;margin-bottom:12px}
    .tab{padding:8px 10px;border-radius:10px;background:transparent;border:1px solid rgba(43,37,33,0.05);cursor:pointer}
    .tab.active{background:var(--accent);color:#fff}
    .exercise{min-height:160px;display:flex;flex-direction:column;gap:10px}
    .breath-circle{width:120px;height:120px;border-radius:50%;margin:12px auto;background:radial-gradient(circle at 30% 30%, rgba(192,138,91,0.12), rgba(138,90,68,0.06));display:flex;align-items:center;justify-content:center;font-weight:700;color:var(--accent)}
    .journal textarea{width:100%;height:100px;padding:10px;border-radius:8px;border:1px solid rgba(43,37,33,0.06);resize:vertical}
    @media (max-width:880px){.hero{grid-template-columns:1fr;}}
    @media (prefers-reduced-motion:reduce){.reveal{transition:none}}
  </style>
</head>
<body>
  <header>
    <div class='nav'>
      <div class='brand'>{{BUSINESS_NAME}}</div>
      <nav style='margin-left:18px;display:flex;gap:6px'>
        <a href='index.html'>Home</a>
        <a href='services.html' aria-current='page'>Offerings</a>
        <a href='conditions.html'>Care Areas</a>
        <a href='approach.html'>Method</a>
        <a href='pricing.html'>Fees</a>
        <a href='book.html' style='margin-left:auto;background:var(--accent);color:#fff;padding:8px 12px;border-radius:8px'>Reserve</a>
        <a href='contact.html'>Connect</a>
      </nav>
    </div>
  </header>
  <main>
    <section class='hero reveal' id='hero'>
      <div class='hero-card'>
        <div class='kicker'>Personalized pathways</div>
        <h1>Thoughtful, realistic interventions for busy lives</h1>
        <p class='lead'>We blend evidence-informed functional assessment with pragmatic planning. Short, clear engagements that surface priorities and leave you with tangible next steps you can actually follow.
        </p>
        <div class='cta-row'>
          <a class='btn btn-primary' href='{{PRIMARY_CTA_URL}}'>{{PRIMARY_CTA_LABEL}}</a>
          <button class='btn btn-alt' id='tryNowBtn'>Try an exercise</button>
        </div>
        <div class='social'>
          <div class='badge'>VIP Day option</div>
          <div style='color:var(--muted);font-size:13px'>Sessions from 30–120 minutes</div>
        </div>
      </div>
      <aside class='hero-card reveal' aria-hidden='false'>
        <h3 style='margin-top:0'>Offerings at a glance</h3>
        <div class='card-list'>
          <div class='service'>
            <h3>Foundations Audit</h3>
            <div class='meta'>Initial deep review • 90 min</div>
            <div class='price'>Starting at $395</div>
          </div>
          <div class='service'>
            <h3>Rhythm Reset</h3>
            <div class='meta'>Three 60-min sessions • 6-week plan</div>
            <div class='price'>Package from $950</div>
          </div>
          <div class='service'>
            <h3>Nourished Living Audit</h3>
            <div class='meta'>Nutrition-focused consult • 60 min</div>
            <div class='price'>Starting at $285</div>
          </div>
          <div class='service'>
            <h3>Integrative VIP Day</h3>
            <div class='meta'>Deep planning day • 4–6 hours</div>
            <div class='price'>Bespoke pricing</div>
          </div>
        </div>
      </aside>
    </section>

    <section class='reveal' id='benefits' style='margin-top:28px'>
      <h2 style='margin-bottom:8px'>Outcomes we emphasize</h2>
      <p style='color:var(--muted);margin-top:0'>We orient each engagement toward three practical outcomes: clarity, doable routines, and measurable shifts you can maintain between visits.</p>
      <div class='process'>
        <div class='step'>
          <strong>Clarity</strong>
          <p class='meta'>Identify what's actually driving day-to-day challenges.</p>
        </div>
        <div class='step'>
          <strong>Small, strategic changes</strong>
          <p class='meta'>Actions you can integrate without rearranging your life.</p>
        </div>
        <div class='step'>
          <strong>Tracking that matters</strong>
          <p class='meta'>Simple measures to know if a plan is working.</p>
        </div>
      </div>
    </section>

    <section class='reveal' id='process' style='margin-top:28px'>
      <h2>How a short program typically flows</h2>
      <ol style='color:var(--muted)'>
        <li><strong>Discovery</strong> — focused intake and prioritization.</li>
        <li><strong>Testing & sequencing</strong> — selective labs or trials when indicated.</li>
        <li><strong>Plan design</strong> — a phased, measurable roadmap.</li>
        <li><strong>Review & iterate</strong> — a check-in loop to refine the plan.</li>
      </ol>
    </section>

    <section class='reveal' id='testimonials' style='margin-top:28px'>
      <h2>What clients notice</h2>
      <div style='display:grid;grid-template-columns:1fr 1fr;gap:12px'>
        <blockquote style='background:#fff;padding:14px;border-radius:10px'>
          "A short set of steps I could actually keep. Better sleep and fewer midday meltdowns."<br><cite style='color:var(--muted)'>— Parent, {{CITY}}</cite>
        </blockquote>
        <blockquote style='background:#fff;padding:14px;border-radius:10px'>
          "We built a plan without overwhelm. The lab guidance was practical and clear."<br><cite style='color:var(--muted)'>— Entrepreneur, {{STATE}}</cite>
        </blockquote>
      </div>
    </section>

    <section class='faq reveal' id='faq' style='margin-top:28px'>
      <h2>Frequently asked questions</h2>
      <details>
        <summary>How long before I see change?</summary>
        <div style='color:var(--muted)'>Changes depend on what we address. Some clients notice improvements in 2–4 weeks when consistent about targeted shifts; others take longer for complex systems. We measure progress and adjust accordingly.</div>
      </details>
      <details>
        <summary>Do you coordinate with my primary care clinician?</summary>
        <div style='color:var(--muted)'>Yes. We share plans and recommendations with your existing team when you consent, and we frame suggestions to be clinically actionable.</div>
      </details>
    </section>

    <section class='reveal' id='cta' style='margin-top:28px;padding:18px;background:linear-gradient(180deg,rgba(200,138,91,0.06),transparent);border-radius:12px'>
      <h3 style='margin:0 0 8px 0'>Ready to clarify next steps?</h3>
      <p style='margin:0;color:var(--muted)'>Book a short Foundations Audit to set priorities and leave with a concrete, time-bound plan.</p>
      <div style='margin-top:12px'>
        <a class='btn btn-primary' href='{{PRIMARY_CTA_URL}}'>Secure a session</a>
        <button class='btn btn-alt' id='tryNowBtn2'>Try an exercise</button>
      </div>
    </section>

  </main>
  <footer>
    <div style='display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px'>
      <div>{{BUSINESS_NAME}} — {{CITY}}, {{STATE}} • <a href='tel:{{PHONE}}' style='color:inherit;text-decoration:none'>{{PHONE}}</a></div>
      <div style='color:var(--muted)'>Questions? <a href='mailto:{{EMAIL}}' style='color:inherit;text-decoration:underline'>{{EMAIL}}</a></div>
    </div>
  </footer>

  <!-- Modal -->
  <div class='modal-backdrop' id='modalBackdrop' role='dialog' aria-modal='true' aria-hidden='true'>
    <div class='modal' role='document'>
      <div style='display:flex;justify-content:space-between;align-items:center'>
        <h3 style='margin:0'>Guided short practice</h3>
        <button id='closeModal' class='tab' aria-label='Close'>Close</button>
      </div>
      <div class='tabs' role='tablist' aria-label='Exercise options' style='margin-top:12px'>
        <button class='tab active' data-mode='breath'>Breathing</button>
        <button class='tab' data-mode='journal'>Quick journal</button>
        <button class='tab' data-mode='intent'>Set intention</button>
      </div>
      <div class='exercise' id='exerciseArea'>
        <!-- dynamic content -->
        <div class='breath' id='breathArea'>
          <div style='text-align:center;color:var(--muted)'>Follow the slow inhale-exhale guide for one minute.</div>
          <div class='breath-circle' id='breathCircle'>Ready</div>
          <div style='display:flex;gap:8px;justify-content:center;margin-top:6px'>
            <button class='btn btn-primary' id='startBreath'>Start</button>
            <button class='btn btn-alt' id='stopBreath'>Stop</button>
          </div>
        </div>
      </div>
    </div>
  </div>

  <script>
    // Scroll reveal with respects to reduced motion
    (function(){
      const prefersReduced = matchMedia('(prefers-reduced-motion: reduce)').matches;
      const items = document.querySelectorAll('.reveal');
      if(prefersReduced){
        items.forEach(el=>el.classList.add('show'));
        return;
      }
      const obs = new IntersectionObserver((entries)=>{
        entries.forEach(e=>{
          if(e.isIntersecting){
            e.target.classList.add('show');
            obs.unobserve(e.target);
          }
        })
      },{threshold:0.12});
      items.forEach(i=>obs.observe(i));
    })();

    // Modal / exercise
    const modal = document.getElementById('modalBackdrop');
    const tryButtons = document.querySelectorAll('#tryNowBtn, #tryNowBtn2');
    const close = document.getElementById('closeModal');
    const tabs = document.querySelectorAll('.tab[data-mode]');
    const exerciseArea = document.getElementById('exerciseArea');
    let breathTimer = null; let breathState = 0; let breathInterval = null;

    tryButtons.forEach(b=>b.addEventListener('click',openModal));
    close.addEventListener('click',closeModal);
    modal.addEventListener('click',e=>{ if(e.target===modal) closeModal(); });

    function openModal(){
      modal.style.display='flex';
      modal.setAttribute('aria-hidden','false');
      activateMode('breath');
    }
    function closeModal(){
      modal.style.display='none';
      modal.setAttribute('aria-hidden','true');
      stopBreathing();
    }
    tabs.forEach(t=>t.addEventListener('click',()=>activateMode(t.getAttribute('data-mode'))));

    function activateMode(mode){
      tabs.forEach(t=>t.classList.toggle('active', t.getAttribute('data-mode')===mode));
      if(mode==='breath') renderBreath();
      if(mode==='journal') renderJournal();
      if(mode==='intent') renderIntent();
    }

    function renderBreath(){
      exerciseArea.innerHTML = "<div class='breath' id='breathArea'><div style='text-align:center;color:var(--muted)'>Follow the slow inhale-exhale guide for one minute.</div><div class='breath-circle' id='breathCircle'>Ready</div><div style='display:flex;gap:8px;justify-content:center;margin-top:6px'><button class='btn btn-primary' id='startBreath'>Start</button><button class='btn btn-alt' id='stopBreath'>Stop</button></div></div>";
      document.getElementById('startBreath').addEventListener('click',startBreathing);
      document.getElementById('stopBreath').addEventListener('click',stopBreathing);
    }

    function startBreathing(){
      const circle = document.getElementById('breathCircle');
      let count = 60; // seconds
      breathState = 0; // 0 inhale,1 hold,2 exhale
      if(breathInterval) clearInterval(breathInterval);
      circle.textContent = '3';
      // simple cycle: inhale 4s, hold 4s, exhale 6s => 14s cycle
      breathInterval = setInterval(()=>{
        breathState = (breathState+1)%3;
        if(breathState===0){ circle.style.transform='scale(1.18)'; circle.textContent='Inhale'; }
        if(breathState===1){ circle.style.transform='scale(1)'; circle.textContent='Hold'; }
        if(breathState===2){ circle.style.transform='scale(0.78)'; circle.textContent='Exhale'; }
        count--;
        if(count<=0){ stopBreathing(); }
      },14000/3);
    }
    function stopBreathing(){
      const circle = document.getElementById('breathCircle');
      if(breathInterval) clearInterval(breathInterval);
      breathInterval=null;
      if(circle) { circle.style.transform='none'; circle.textContent='Done'; }
    }

    function renderJournal(){
      exerciseArea.innerHTML = "<div class='journal'><div style='color:var(--muted)'>Spend 5–10 minutes answering one prompt.</div><textarea id='journalText' placeholder='What matters most this week?'></textarea><div style='display:flex;gap:8px;justify-content:flex-end;margin-top:6px'><button class='btn btn-alt' id='saveJournal'>Save</button><button class='btn btn-primary' id='clearJournal'>Clear</button></div></div>";
      const save = document.getElementById('saveJournal');
      const clear = document.getElementById('clearJournal');
      const ta = document.getElementById('journalText');
      save.addEventListener('click',()=>{
        localStorage.setItem('quick_journal', ta.value || '');
        save.textContent='Saved'; setTimeout(()=>save.textContent='Save',900);
      });
      clear.addEventListener('click',()=>{ ta.value=''; localStorage.removeItem('quick_journal'); });
      const existing = localStorage.getItem('quick_journal'); if(existing) ta.value = existing;
    }

    function renderIntent(){
      exerciseArea.innerHTML = "<div style='display:flex;flex-direction:column;gap:8px'><div style='color:var(--muted)'>Name one practical intention and a single next action.</div><input id='intentText' placeholder='My intention...' style='padding:10px;border-radius:8px;border:1px solid rgba(43,37,33,0.06)'><input id='intentAction' placeholder='Next action...' style='padding:10px;border-radius:8px;border:1px solid rgba(43,37,33,0.06)'><div style='display:flex;gap:8px;justify-content:flex-end'><button class='btn btn-primary' id='saveIntent'>Keep it</button></div></div>";
      document.getElementById('saveIntent').addEventListener('click',()=>{
        const i = document.getElementById('intentText').value || ''; const a = document.getElementById('intentAction').value || '';
        localStorage.setItem('quick_intent', JSON.stringify({i,a,time:Date.now()}));
        document.getElementById('saveIntent').textContent='Saved'; setTimeout(()=>document.getElementById('saveIntent').textContent='Keep it',900);
      });
    }

  </script>
</body>
</html>"} 
